def soln(n: int, m: int) -> int:
	if n >= m:
		great = '1'
		less = '0'
	else:
		great = '0'
		less = '1'
	s = less
	for i in range(min(n, m)):
		s += great + less
	if n == m:
		s += great
		print(len(s))
		print(s)
		return
	for i in range(abs(n - m)):
		s += great + less * 2
	print(len(s) - 1)
	print(s[:len(s) - 1])
for _ in range(int(input())):
	(n, m) = map(int, input().split())
	soln(n, m)
